import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l2_p89_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor tail_fused_cuda(torch::Tensor x, torch::Tensor subtract);

torch::Tensor tail_fused(torch::Tensor x, torch::Tensor subtract) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(subtract.is_cuda(), "subtract must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 5, "x must be 5D (N, C, D, H, W)");
    TORCH_CHECK(subtract.dim() == 1, "subtract must be 1D (C)");
    TORCH_CHECK(x.size(1) == subtract.size(0), "channel dimension mismatch");
    return tail_fused_cuda(x.contiguous(), subtract.contiguous());
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("tail_fused", &tail_fused, "Fused softmax-subtract-swish-max tail");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

__device__ __forceinline__ float warp_reduce_max(float val) {
    for (int offset = 16; offset > 0; offset /= 2) {
        val = fmaxf(val, __shfl_down_sync(0xffffffff, val, offset));
    }
    return val;
}

__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = 16; offset > 0; offset /= 2) {
        val += __shfl_down_sync(0xffffffff, val, offset);
    }
    return val;
}

__global__ void tail_fused_kernel(
    const float* __restrict__ x,
    const float* __restrict__ subtract,
    float* __restrict__ out,
    int N, int C, int D, int H, int W
) {
    int spatial_size = D * H * W;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int n = idx / spatial_size;
    int spatial_idx = idx % spatial_size;

    if (n >= N) return;

    int d = spatial_idx / (H * W);
    int hw = spatial_idx % (H * W);
    int h = hw / W;
    int w = hw % W;

    extern __shared__ float smem[];
    float* channel_vals = smem;

    // First pass: find max for numerical stability
    float local_max = -FLT_MAX;
    for (int c = 0; c < C; c++) {
        int offset = ((n * C + c) * D + d) * H * W + h * W + w;
        float val = __ldg(&x[offset]);
        local_max = fmaxf(local_max, val);
        channel_vals[c] = val;
    }

    // Second pass: compute exp and sum
    float sum_exp = 0.0f;
    for (int c = 0; c < C; c++) {
        float val = expf(channel_vals[c] - local_max);
        channel_vals[c] = val;
        sum_exp += val;
    }

    // Third pass: normalize softmax, subtract, swish, and find max
    float final_max = -FLT_MAX;
    for (int c = 0; c < C; c++) {
        float softmax_val = channel_vals[c] / sum_exp;
        float after_sub = softmax_val - subtract[c];
        float sigmoid_val = 1.0f / (1.0f + expf(-after_sub));
        float swish_val = after_sub * sigmoid_val;
        final_max = fmaxf(final_max, swish_val);
    }

    out[idx] = final_max;
}

torch::Tensor tail_fused_cuda(torch::Tensor x, torch::Tensor subtract) {
    int N = x.size(0);
    int C = x.size(1);
    int D = x.size(2);
    int H = x.size(3);
    int W = x.size(4);

    int spatial_size = D * H * W;
    int total_voxels = N * spatial_size;

    auto out = torch::empty({N, D, H, W}, x.options());

    int threads = 256;
    int blocks = (total_voxels + threads - 1) / threads;
    int smem_size = C * sizeof(float);

    tail_fused_kernel<<<blocks, threads, smem_size>>>(
        x.data_ptr<float>(),
        subtract.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, D, H, W
    );

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        A model that performs a sequence of operations:
            - ConvTranspose3d
            - MaxPool3d
            - Softmax
            - Subtract
            - Swish
            - Max
        """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, pool_kernel_size, pool_stride, pool_padding):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, output_padding=output_padding)
        self.max_pool = nn.MaxPool3d(kernel_size=pool_kernel_size, stride=pool_stride, padding=pool_padding)
        self.subtract = nn.Parameter(torch.randn(out_channels))
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        x = self.conv_transpose(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        x = self.max_pool(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        x = _stark_get_extension().tail_fused(x, self.subtract)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        # subtract handled in fused kernel
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        # swish handled in fused kernel
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_6>>>
        # channel max handled in fused kernel
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_7>>>
        return x
        # <<<END_IMPROVE>>>

